      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n                        <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n                        <text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text>\n                        <rect x=\"150\" y=\"120\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/>\n                        <text x=\"550\" y=\"175\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">BIRTHDAY RULE (NAIC)</text>\n                        <text x=\"550\" y=\"215\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">Determines primary plan for dependent children</text>\n                        <text x=\"550\" y=\"255\" text-anchor=\"middle\" fill=\"#888\" font-size=\"16\">Earlier birthday in calendar year = primary</text>\n                        <text x=\"550\" y=\"290\" text-anchor=\"middle\" fill=\"#888\" font-size=\"16\">Not about age -- about month/day position</text>\n                        <rect x=\"150\" y=\"380\" width=\"370\" height=\"120\" rx=\"15\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/>\n                        <text x=\"335\" y=\"425\" text-anchor=\"middle\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"20\">Parent A: Oct 3</text>\n                        <text x=\"335\" y=\"465\" text-anchor=\"middle\" fill=\"#888\" font-size=\"16\">Later in calendar year</text>\n                        <text x=\"335\" y=\"490\" text-anchor=\"middle\" fill=\"#888\" font-size=\"16\">= SECONDARY</text>\n                        <rect x=\"580\" y=\"380\" width=\"370\" height=\"120\" rx=\"15\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                        <text x=\"765\" y=\"425\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"20\">Parent B: Apr 18</text>\n                        <text x=\"765\" y=\"465\" text-anchor=\"middle\" fill=\"#10b981\" font-size=\"16\">Earlier in calendar year</text>\n                        <text x=\"765\" y=\"490\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"16\">= PRIMARY</text>\n                    </svg>",
